import React, { useState, useEffect } from "react";
import { initializeApp, getApps } from "firebase/app";
import { getDatabase, ref, set, onValue } from "firebase/database";
import GridSender from "./GridSender";
import AnimatedReceiverGrid from "./UnifiedGrid";

const firebaseConfig = {
  apiKey: "AIzaSyAnVoul_IT33Dj55D4ewKygR1yguwc6zhA",
  authDomain: "interference-5162f.firebaseapp.com",
  projectId: "interference-5162f",
  storageBucket: "interference-5162f.appspot.com",
  messagingSenderId: "548311176122",
  appId: "1:548311176122:web:aa9238009686697b754383",
  measurementId: "G-VVBCV2BPN4",
  databaseURL: "https://interference-5162f-default-rtdb.firebaseio.com"
};

const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];
const db = getDatabase(app);

const UnifiedGrid = ({ isSender, showAnimation = false, showControls = true }) => {
  const [text, setText] = useState("INTERFERENCE");
  const [timeLevel, setTimeLevel] = useState(7);
  const [outsideLevel, setOutsideLevel] = useState(2);
  const [feelingLevel, setFeelingLevel] = useState(4);
  const [insideLevel, setInsideLevel] = useState(1);

  useEffect(() => {
    if (isSender) {
      const sync = setInterval(() => {
        set(ref(db, "shared"), {
          text,
          timeLevel,
          outsideLevel,
          feelingLevel,
          insideLevel
        });
      }, 500);
      return () => clearInterval(sync);
    } else {
      const sharedRef = ref(db, "shared");
      onValue(sharedRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
          setText(data.text || "");
          setTimeLevel(data.timeLevel || 1);
          setOutsideLevel(data.outsideLevel || 1);
          setFeelingLevel(data.feelingLevel || 1);
          setInsideLevel(data.insideLevel || 1);
        }
      });
    }
  }, [isSender]);

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key.length === 1) setText((prev) => prev + e.key);
      else if (e.key === "Backspace") setText((prev) => prev.slice(0, -1));
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  if (isSender) {
    return (
      <GridSender
        text={text}
        timeLevel={timeLevel}
        setTimeLevel={setTimeLevel}
        outsideLevel={outsideLevel}
        setOutsideLevel={setOutsideLevel}
        feelingLevel={feelingLevel}
        setFeelingLevel={setFeelingLevel}
        insideLevel={insideLevel}
        setInsideLevel={setInsideLevel}
        isSender={true}
      />
    );
  } else {
    return (
      <AnimatedReceiverGrid
        text={text}
        timeLevel={timeLevel}
        outsideLevel={outsideLevel}
        feelingLevel={feelingLevel}
        insideLevel={insideLevel}
        isSender={false}
        showAnimation={showAnimation}
        showControls={showControls}
      />
    );
  }
};

export const SenderGrid = (props) => (
  <UnifiedGrid
    {...props}
    isSender={true}
    showAnimation={true}
    showControls={true}
  />
);

export const ReceiverGrid = (props) => (
  <UnifiedGrid
    {...props}
    isSender={false}
    showAnimation={true}
    showControls={false}
  />
);

export default UnifiedGrid;
