import React from "react";
import { HashRouter as Router, Routes, Route } from "react-router-dom";
import UnifiedGrid from "./RoutesSetup";

function App() {
  return (
    <Router>
      <Routes>
       <Route path="/sender" element={<UnifiedGrid isSender={true} />} />
        <Route path="/receiver" element={<UnifiedGrid isSender={false} />} />
        <Route
        path="*"
        element={
          <h1 style={{ color: "white", textAlign: "center" }}>
            Page not found
          </h1>
    }
  />
</Routes>
    </Router>
  );
}

export default App;